('pkg1a063c5895c6v0fo2', 'sv1a063c5895cjffecy', '', 'Burns Management', '', 'Electrical contact burns', 'BM004A', 'Electrical contact burns: Low voltage - without part of limb / limb loss; Includes % TBSA skin grafted, flap cover, follow-up dressings etc. as deemed necessary; Surgical procedures are required for deep burns that are not amenable to heal with dressings alone.', 25500, 'Public EHCP', 0, '', '', ''),
('pkg1a063c5895cdhcv9c', 'sv1a063c5895cjffecy', '', 'Burns Management', '', 'Electrical contact burns', 'BM004B', 'Electrical contact burns: Low voltage - with part of limb / limb loss; Includes % TBSA skin grafted, flap cover, follow-up dressings Amputation etc. as deemed necessary; Surgical procedures are required for deep burns that are not amenable to heal with dressings alone.', 34000, 'Public EHCP', 0, '', '', ''),
('pkg1a063c5895c0j2ne4', 'sv1a063c5895cjffecy', '', 'Burns Management', '', 'Electrical contact burns', 'BM004C', 'Electrical contact burns: High voltage - with part of limb / limb loss; Includes % TBSA skin grafted, flap cover,fasciotomy +/- /amputation/Central IV Line/debridement/early skin grafting pedicle or free flap coverage,follow- up dressings etc. as deemed necessary; Surgical procedures are required for deep burns that are not amenable to heal with dressings alone.', 51000, 'Public EHCP', 0, '', '', ''),
('pkg1a063c5895cydx8b3', 'sv1a063c5895cjffecy', '', 'Burns Management', '', 'Electrical contact burns', 'BM004D', 'Electrical contact burns: High voltage - without part of limb / limb loss; Includes % TBSA skin grafted, flap cover, fasciotomy +/- /debridement/early skin grafting/flap cover: pedicle or free flap coverage,follow-up dressings etc. as deemed necessary; Surgical procedures are required for deep burns that are not amenable to heal with dressings alone.', 42500, 'Public EHCP', 0, '', '', ''),
('pkg1a063c5895cdhtzcl', 'sv1a063c5895cjffecy', '', 'Burns Management', '', 'Chemical burns', 'BM005A', 'Chemical burns: Without significant facial scarring and/or loss of function; Includes % TBSA skin grafted, flap cover, follow-up dressings etc. as deemed necessary; Surgical procedures are required for deep burns that are not amenable to heal with dressings alone.(Similar to therma burns require more grafting, debridement,(skin grafing/canthopexy)', 34000, 'Public EHCP', 0, '', '', ''),
('pkg1a063c5895cd0m6iy', 'sv1a063c5895cjffecy', '', 'Burns Management', '', 'Chemical burns', 'BM005B', 'Chemical burns: With significant facial scarring and/or loss of function; Includes % TBSA skin grafted, flap cover,debridement,skin grafting,follow-up dressings etc. as deemed necessary; Surgical procedures are required for deep burns that are not amenable to heal with dressings alone.', 51000, 'Public EHCP', 0, '', '', ''),
('pkg1a063c5895c1jzj22', 'sv1a063c5895cjffecy', '', 'Burns Management', '', 'Post Burn Contracture surgeries for Functional Improvement', 'BM006A', 'Post Burn Contracture surgeries for Functional Improvement (Package including splints, pressure garments, silicone - gel sheet and physiotherapy): Excluding Neck contracture; Contracture release with - Split thickness Skin Graft (STSG) / Full Thickness Skin Graft (FTSG) / Flap cover is done for each joint with post - operative regular dressings for STSG / FTSG / Flap cover.', 41875, 'Public EHCP', 0, '', '', ''),
('pkg1a063c5895crnmxwc', 'sv1a063c5895cjffecy', '', 'Burns Management', '', 'Post Burn Contracture surgeries for Functional Improvement', 'BM006B', 'Post Burn Contracture surgeries for Functional Improvement (Package including splints, pressure garments,contracture release & split skin graft with or without flap reconstruction,silicone - gel sheet and physiotherapy): Neck contracture; Contracture release with - Split thickness Skin Graft (STSG) / Full Thickness Skin Graft (FTSG) / Flap cover is done for each joint with post-operative regular dressings for STSG / FTSG / Flap cover.', 42500, 'Public EHCP', 0, '', '', ''),
